import pickle

def pickle_access(app, method):
    # VULNERABILITY: pickle.loads() deserializes untrusted data and can execute arbitrary Python code
    result = pickle.loads(app.attr[method])
    return result

@method
def compile(app):
    # VULNERABILITY: pickle.loads() on untrusted data can execute arbitrary code via pickle exploit
    pickle_access(app, "ast")

